test('SC1 prospective planner refuses wrong epoch and leaves frozen old authority usable', async () => {
  const fixture = await import('../fixtures/dependency-owner-custody');
  const request = await coupledBuildRequest();
  const admitted = fixture.decodeOrdinaryCoupledBuildRequestV1(request);
  const physicalRoot = new URL('../../../../', import.meta.url).pathname.replace(/\/$/, '');
  const supplied = new Map<string, Uint8Array>();
  for (const pin of fixture.ordinaryHoldSourceEpochV1.pins)
    supplied.set(`${request.sourceRoot}/${pin.relative}`, await readFile(`${physicalRoot}/${pin.relative}`));
  const old = fixture.planOrdinaryCoupledBuildV1(request.sourceRoot, supplied, request.patch, request.manifest);
  fixture.assertOrdinaryCoupledPlanV1(admitted, old);
  for (const epoch of [undefined, null, 'ordinary-uc2-coupled-setup-v1-near', old.sourceEpoch]) {
    expect(() => fixture.planOrdinarySetupCustodyBuildV1('', new Map(), new Uint8Array(), new Uint8Array(), epoch)).toThrow('setup custody source epoch');
  }
  const prospective = fixture.planOrdinarySetupCustodyBuildV1(request.sourceRoot, supplied, request.patch, request.manifest, 'ordinary-uc2-coupled-setup-v1');
  expect(prospective.sourceEpoch).toBe('ordinary-uc2-coupled-setup-v1');
  expect(prospective.layers).toEqual(old.layers);
  expect([...prospective.materialized]).toEqual([...old.materialized]);
  expect(prospective.appliedCuts).toEqual(old.appliedCuts);
  expect(prospective.entrySource).toBe(old.entrySource);
  expect(prospective.portSources.size).toBe(31);
  expect(() => fixture.assertOrdinaryCoupledPlanV1(admitted, prospective as unknown as typeof old)).toThrow('coverage bytes');
  expect(() => fixture.decodeOrdinaryCoupledBuildRequestV1({...request, sourceEpoch:prospective.sourceEpoch})).toThrow();
  const changed = [...old.portSources].filter(([name,source]) => prospective.portSources.get(name) !== source).map(([name]) => name);
  expect(changed).toEqual(['ordinary-hold-v1:ledger','ordinary-hold-v1:setup-participant-fs','ordinary-hold-v1:setup-complete-fs','ordinary-hold-v1:setup-startup-fs','ordinary-hold-v1:setup-database-fs','ordinary-hold-v1:setup-frontend-fs','ordinary-hold-v1:setup-namespace-fs','ordinary-hold-v1:migration-call','ordinary-hold-v1:setup-complete-write','ordinary-hold-v1:setup-namespace-write','ordinary-hold-v1:controller']);
  expect(prospective.portSources.get('ordinary-hold-v1:controller')).toContain("sourceEpoch:'ordinary-uc2-coupled-setup-v1'");
  const bootstrapPins = [
    ['known-initial-prepared-release','057a352882e87c983decde056d7677e9b9e6b69102289b2378e285ba00516ca9'],
    ['known-preawait-manifest-refusal','98f40fa7dfc7e9631a29a44cd55a0da20e8e38a9dddba26f10af297167c86d1c'],
  ];
  for (const [caseId,digest] of bootstrapPins) {
    const historical = fixture.ordinaryKnownBootstrapSourceV1('/owned/ordinary-known-image.js', caseId);
    expect(createHash('sha256').update(historical).digest('hex')).toBe(digest);
    expect(fixture.ordinarySetupCustodyBootstrapSourceV1('/owned/ordinary-known-image.js', caseId)).toBe(historical.replaceAll(old.sourceEpoch, prospective.sourceEpoch));
  }
});

