test('SC1 total cap refuses exact plus1 independently of boundary caps', async () => {
  const ledger = await setupLedger();
  const {limits, total} = ledger.inspectSetupLedger();
  let entries = 0;
  const provider = () => { entries++; return Promise.resolve(); };
  let remaining = total;
  for (const [label, limit] of Object.entries(limits)) {
    const count = Math.min(limit, remaining);
    for (let ordinal = 0; ordinal < count; ordinal++) ledger.invokeSetupPromise(label, provider, undefined, []);
    remaining -= count;
  }
  expect(remaining).toBe(0);
  expect(() => ledger.invokeSetupPromise('setup.startup.chmod', provider, undefined, [])).toThrow('setup total cap');
  expect(entries).toBe(total);
  await ledger.joinSetupOperations();
});

