  }
  /** Calls each original close at most once; a throw records UNKNOWN rather than authorizing retry. */
  private attemptClose(resource: OwnedResource): void {
    if (resource.outcome.status !== 'unattempted') return;
    try {
      if (resource.kind === 'stream') resource.directory.closeSync();
      else closeSync(resource.descriptor);
      resource.outcome = { status: 'closed' };
      this.resources.delete(resource);
    } catch (failure) {
      resource.outcome = { status: 'unknown', failure };
    }
  }
  /** Unknown temporary cleanup revokes work with a retained failure; originals await the terminal sweep. */
  private closeTransient(resource: OwnedResource): void {
    this.attemptClose(resource);
    if (resource.outcome.status === 'unknown') {
      const failure = createCleanupFailure([resource.outcome.failure], [...this.resources]);
      this.operationFailures.push(failure);
      this.lifecycle = { status: 'revoked', failure };
      throw failure;
    }
  }
  /** A local validation/read refusal must survive an independently unknown cleanup outcome. */
  private closeAfterFailure(resource: OwnedResource, cause: unknown): never {
    this.attemptClose(resource);
    if (resource.outcome.status === 'unknown') {
      const failure = createCleanupFailure([cause, resource.outcome.failure], [...this.resources]);
      this.operationFailures.push(cause, failure);
      this.lifecycle = { status: 'revoked', failure };
      throw failure;
    }
    throw cause;
  }
  /** Sweeps all originals even after expiry. Failed cleanup permanently rethrows the same retained error. */
  closeFiles(primary?: { readonly failure: unknown }): void {
    if (this.lifecycle.status === 'closed') return;
    if (this.lifecycle.status === 'failed') throw this.lifecycle.failure;
    if (this.lifecycle.status === 'closing') refuseGraph('cleanup already in progress');
    this.lifecycle = { status: 'closing' };
    const custody = [...this.resources];
    for (const resource of custody) if (resource.kind !== 'parent') this.attemptClose(resource);
    for (const resource of custody) if (resource.kind === 'parent') this.attemptClose(resource);
    const failures: unknown[] = [];
    for (const resource of custody)
      if (resource.outcome.status === 'unknown') failures.push(resource.outcome.failure);
    if (failures.length !== 0) {
      const failure = createCleanupFailure(
        [
          ...(primary === undefined ? [] : [primary.failure]),
          ...this.operationFailures,
          ...failures,
        ],
        custody,
      );
      this.lifecycle = { status: 'failed', failure };
      throw failure;
    }
    this.lifecycle = { status: 'closed' };
    this.files.clear();
    this.directories.clear();
    this.absences.clear();
    this.rosters.clear();
  }
}

/** Stored read-only closure only; this returns no original owner, restoration capability or startup callback. */
export interface InitialHandoffGraph {
  readonly admission: CompleteDependencyActivationRequest;
  readonly runtimeLaunch: RuntimeLaunchPins;
  readonly writerManifest: WriterManifest;
  readonly images: readonly SolverRestorationImage[];
  retainExecutingFile(observed: SolverFile): void;
  verifyClosure(): void;
  assertStable(): void;
  closeFiles(): void;
}

interface GraphContext {
  readonly files: ContentFiles;
  readonly directory: string;
  readonly owner: string;
  readonly publication: ReturnType<typeof decodeDependencyOwnerPublication>;
  readonly labels: Map<string, string>;
}
function captureReference(
  context: GraphContext,
  selected: Reference,
  label: string,
  consumer?: string,
): { file: ContentFile; fields: Fields } {
  context.files.retainEdge(selected, consumer);
  const prior = context.labels.get(selected.name);
  const binding = label + ':' + selected.sha256;
  if (prior !== undefined && prior !== binding) refuseGraph('reference binding conflicts');
  context.labels.set(selected.name, binding);
  const file = context.files.captureText(join(context.directory, selected.name), 65536);
  if (file.sha256 !== selected.sha256) refuseGraph('reference hash differs');
  const envelope = readClosed(parseJson(file.contents), ['owner', 'record']);
  if (envelope['owner'] !== context.owner) refuseGraph('original owner bytes differ');
  decodeDependencyOwnerPublication(parseJson(readString(envelope['owner'])));
  return { file, fields: readFields(envelope['record']) };
}

interface Database {
  readonly environment: EnvName;
  readonly path: string;
  readonly host: string;
  readonly directoryIdentity: string;
  readonly fileIdentity: string;
}
interface ParticipantSelection {
  readonly role: 'backend' | 'gateway' | 'source';
  readonly id: string;
  readonly originalPolicy: { readonly name: string; readonly maximumRetryCount: number };
}
interface Participants {
  readonly fields: Fields;
  readonly backend: { id: string; image: string; imageId: string };
  readonly gateway: { id: string; image: string; imageId: string };
  readonly source: {
    id: string;
    runtimeReference: string;
    runtimeImageId: string;
    manifestSha256: string;
    environmentSha256: string;
  };
  readonly databases: readonly Database[];
  readonly solverIntent: Reference;
  readonly fences: Fields;
