    if (readHash(authorities[key]) !== admission.authorities.pins[key])
      refuseGraph('participants authority pins differ');
  if (
    !/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/.test(
      readString(authorities['bootId']),
