export function scanMigrationArtifact(...args:Parameters<typeof original>):ReturnType<typeof original>{const scanner=args[2]===true?reserveScanner(args):undefined;const operation=reserveOperation('complete.scanner','promise',undefined,args);const call=reserveScannerCall(args);try{const returned=attachScannerCall(call,attachPromise(operation,Reflect.apply(original,undefined,args)));return scanner===undefined?returned:attachScannerPromise(scanner,returned);}catch(cause){throwOperation(operation,cause);throwScannerCall(call,cause);if(scanner!==undefined)throwScanner(scanner,cause);throw cause;}}`,
