    F: ordinaryHoldClosureIntegerV1(counts['F']),
    D: ordinaryHoldClosureIntegerV1(counts['D']),
    L: ordinaryHoldClosureIntegerV1(counts['L']),
    A: ordinaryHoldClosureIntegerV1(counts['A']),
  });
