    sourceRootCanonical,
    compilerCwd,
    readLeaseAssumption,
    files,
    directories,
    symlinks,
    absences,
    compilerInputs,
    virtualInputs,
    generatedEntry,
    historicalSourcePins,
    census,
    closureOperationCount: ordinaryHoldClosureIntegerV1(packet['closureOperationCount']),
