function decodePointer(contents: string, policy: ActiveEdgePolicy, policyContents: string): Fields {
  const pointer = decodeRecord(parseJson(contents), 'dependency-edge-handoff', [
    'phase',
    'ownerPublicationSha256',
    'policySha256',
    'handoff',
