  const contents = `${JSON.stringify({ owner: ownership.publication, record })}\n`;
  const directory = await open(
    ownership.directory,
    constants.O_RDONLY | constants.O_DIRECTORY | constants.O_NOFOLLOW,
  );
  try {
    const parent = await directory.stat({ bigint: true });
