      const named = await lstat(statePath, { bigint: true });
      if (
        !parent.isDirectory() ||
        !named.isDirectory() ||
        parent.dev !== named.dev ||
        parent.ino !== named.ino ||
        (await realpath(statePath)) !== statePath
      )
        throw new Error('activation owner evidence parent changed');
    }
