  const runtimeLaunch = decodeRuntimeLaunchPins(
    admissionFields['runtimeLaunch'],
    publication.plan.sha,
    authorityPins,
  );
  const sourceFields = readClosed(admissionFields['source'], [
    'pins',
    'runtimeReference',
    'manifest',
  ]);
