const exclusions = new WeakMap<CompleteDependencyExclusion, CompleteScope>();
/** Resolves only the exact live token association; full observation remains the async assertion's job. */
export function lookupCompleteDependencyPreparation(
  owner: DependencyOwner,
  token: CompleteDependencyExclusion,
): DependencyPreparation {
  const scope = exclusions.get(token);
  if (scope?.owner !== owner) throw new Error('complete dependency exclusion is not live');
  assertDependencyPreparation(owner, scope.preparation);
  return scope.preparation;
