function fingerprint(raw: Record<string, unknown>) {
  const host = { ...readFields(raw['HostConfig']) };
  delete host['RestartPolicy'];
  return hashActivationBytes(
    JSON.stringify({
      Config: raw['Config'],
      HostConfig: host,
      Mounts: orderMounts(raw['Mounts']),
      Path: raw['Path'],
      Args: raw['Args'],
    }),
  );
}
